t.script:
window.healthPWAConfig = {
    userId: ,
    userName: '',
    companyName: '',
    companyPhone: '',
    dbName: '',
    user_lang: '',
    apiBaseUrl: '/health_pwa/api',
    syncUrl: '/health_pwa/sync',
    websocketUrl: '/longpolling',
    version: '1.13.1',
    buildTime: '',
    showInstallOverlay: truefalse,
};

// Language switching function for PWA app
window.PWA_switchLanguage = function(lang, skipReload) {
    console.log('=== PWA Language Switch Debug ===');
    console.log('Switching to language:', lang);
    console.log('Current healthPWAConfig.user_lang:', window.healthPWAConfig.user_lang);
    console.log('Current Odoo lang:', window.odoo?.session_info?.user_context?.lang);
    console.log('Skip reload:', skipReload);

    // Update active button state
    const viBtn = document.getElementById('pwa-lang-btn-vi');
    const enBtn = document.getElementById('pwa-lang-btn-en');

    if (viBtn && enBtn) {
        if (lang === 'vi') {
            viBtn.style.background = '#1565C0';
            viBtn.style.color = 'white';
            enBtn.style.background = 'transparent';
            enBtn.style.color = '#666';
        } else {
            enBtn.style.background = '#1565C0';
            enBtn.style.color = 'white';
            viBtn.style.background = 'transparent';
            viBtn.style.color = '#666';
        }
    }

    // Show/hide language-specific content
    document.querySelectorAll('.pwa-lang-content').forEach(el => {
        if (el.getAttribute('data-lang') === lang) {
            el.style.display = '';
        } else {
            el.style.display = 'none';
        }
    });

    // Save preference to localStorage
    localStorage.setItem('pwa_preferred_language', lang);

    // Update healthPWAConfig for PWAUtils
    const newLangCode = lang === 'vi' ? 'vi_VN' : 'en_US';
    window.healthPWAConfig.user_lang = newLangCode;

    console.log('Updated healthPWAConfig.user_lang to:', newLangCode);
    console.log('Testing PWAUtils.i18n.t("Day"):', window.PWAUtils?.i18n?.t('Day'));
    console.log('Testing PWAUtils.i18n.t("Week"):', window.PWAUtils?.i18n?.t('Week'));
    console.log('Testing PWAUtils.i18n.t("Month"):', window.PWAUtils?.i18n?.t('Month'));

    // Reload page to apply language change to Vue app (unless skipReload is true for initial load)
    if (!skipReload) {
        if (confirm(lang === 'vi'
            ? 'Tải lại trang để áp dụng ngôn ngữ mới?'
            : 'Reload page to apply new language?')) {
            window.location.reload();
        }
    }

    console.log('=== End Language Switch Debug ===');
};

// Initialize language on page load (runs after PWAUtils is loaded)
(function initPWALanguage() {
    console.log('=== Initializing PWA Language on Page Load ===');

    const userLang = window.healthPWAConfig?.user_lang || 'vi_VN';
    const savedLang = localStorage.getItem('pwa_preferred_language');

    console.log('User profile language:', userLang);
    console.log('Saved localStorage preference:', savedLang);

    let initialLang = 'vi';

    // Priority: 1. Saved preference, 2. User profile preference, 3. Default
    if (savedLang) {
        initialLang = savedLang;
        console.log('Using saved preference:', savedLang);
    } else if (userLang && userLang.startsWith('en')) {
        initialLang = 'en';
        console.log('Using user profile preference: en');
    } else {
        console.log('Using default: vi');
    }

    // Apply initial language without reload
    if (typeof window.PWA_switchLanguage === 'function') {
        window.PWA_switchLanguage(initialLang, true);
        console.log('=== Language Initialization Complete ===');
    } else {
        console.error('PWA_switchLanguage function not found!');
    }
})();

                if ('serviceWorker' in navigator) {
                    let refreshing = false;
                    const PWA_SW_VERSION = '1.13.1';
                    console.log('[PWA] registering service worker version', PWA_SW_VERSION);

                    // Detect when service worker updates and reload
                    navigator.serviceWorker.addEventListener('controllerchange', function() {
                        if (!refreshing) {
                            refreshing = true;
                            console.log('New service worker activated, reloading...');
                            window.location.reload();
                        }
                    });

                    window.addEventListener('load', function() {
                        // Register SW with a stable versioned URL to avoid endless update loops
                        const swUrl = `/health_pwa/service-worker.js?v=${PWA_SW_VERSION}`;
                        navigator.serviceWorker.register(swUrl)
                            .then(function(registration) {
                                console.log('[PWA] SW registered', swUrl, registration);

                                // Mark PWA as installed if there's an active service worker
                                if (navigator.serviceWorker.controller) {
                                    localStorage.setItem('pwa-sw-installed', 'true');
                                    console.log('Marked PWA as previously installed');
                                }

                                // Check for waiting service worker immediately (in case update happened before page load)
                                if (registration.waiting) {
                                    console.log('[PWA] Update already waiting, showing banner immediately');
                                    showUpdateBanner(registration);
                                }

                                // Check for updates immediately on load
                                registration.update().then(function() {
                                    console.log('[PWA] Initial update check completed');
                                });

                                // Check for updates every 30 seconds (more aggressive)
                                setInterval(function() {
                                    console.log('[PWA] Checking for updates...');
                                    registration.update();
                                }, 30000);

                                // Check for updates on page focus
                                document.addEventListener('visibilitychange', function() {
                                    if (!document.hidden) {
                                        console.log('[PWA] Page visible, checking for updates...');
                                        registration.update();
                                    }
                                });

                                // Handle updates
                                registration.addEventListener('updatefound', function() {
                                    const newWorker = registration.installing;
                                    console.log('[PWA] New service worker found, installing...');

                                    // Check if PWA was previously installed
                                    const isPWAInstalled = localStorage.getItem('pwa-sw-installed') === 'true';
                                    console.log('[PWA] PWA previously installed:', isPWAInstalled);

                                    newWorker.addEventListener('statechange', function() {
                                        console.log('[PWA] New worker state:', newWorker.state);
                                        if (newWorker.state === 'installed') {
                                            // Show banner if this is an update (PWA was previously installed OR there's a controller)
                                            if (isPWAInstalled || navigator.serviceWorker.controller) {
                                                console.log('Update detected, showing update banner');
                                                showUpdateBanner(registration);
                                            } else {
                                                console.log('First install, no banner');
                                            }
                                            // Mark PWA as installed for next time
                                            localStorage.setItem('pwa-sw-installed', 'true');
                                        }
                                    });
                                });

                                // === Push Notification Subscription ===
                                // Platform-aware: Android auto-subscribes, iOS needs user gesture
                                if ('Notification' in window && 'PushManager' in window) {
                                    const isIOS = /iPad|iPhone|iPod/.test(navigator.userAgent);
                                    const isStandalone = window.matchMedia('(display-mode: standalone)').matches || window.navigator.standalone;

                                    // Helper: actual subscription logic (reused by both paths)
                                    window._pwaPushSubscribe = async function() {
                                        try {
                                            // Fetch VAPID key first
                                            const vapidResp = await fetch('/health_pwa/api/push/vapid-key');
                                            const vapidData = await vapidResp.json();
                                            if (!vapidData.success || !vapidData.data.enabled || !vapidData.data.vapid_public_key) {
                                                console.log('[PWA Push] Push not enabled on server');
                                                return false;
                                            }

                                            // Check existing subscription
                                            const existingSub = await registration.pushManager.getSubscription();
                                            if (existingSub) {
                                                // Verify VAPID key hasn't changed
                                                const currentKey = existingSub.options && existingSub.options.applicationServerKey;
                                                if (currentKey) {
                                                    // Key matches — already subscribed correctly
                                                    console.log('[PWA Push] Already subscribed');
                                                    // Re-send to server in case it was lost
                                                    var sj = existingSub.toJSON();
                                                    await fetch('/health_pwa/api/push/subscribe', {
                                                        method: 'POST',
                                                        headers: { 'Content-Type': 'application/json' },
                                                        body: JSON.stringify({ endpoint: sj.endpoint, keys: sj.keys }),
                                                    });
                                                    return true;
                                                }
                                                // VAPID key changed — unsubscribe old and re-subscribe
                                                console.log('[PWA Push] VAPID key changed, re-subscribing...');
                                                await existingSub.unsubscribe();
                                            }
                                            const permission = await Notification.requestPermission();
                                            if (permission !== 'granted') {
                                                console.log('[PWA Push] Permission denied');
                                                return false;
                                            }
                                            const vapidKey = vapidData.data.vapid_public_key;
                                            const padding = '='.repeat((4 - vapidKey.length % 4) % 4);
                                            const base64 = (vapidKey + padding).replace(/-/g, '+').replace(/_/g, '/');
                                            const rawData = atob(base64);
                                            const appServerKey = new Uint8Array(rawData.length);
                                            for (let i = 0; i < rawData.length; i++) {
                                                appServerKey[i] = rawData.charCodeAt(i);
                                            }
                                            const subscription = await registration.pushManager.subscribe({
                                                userVisibleOnly: true,
                                                applicationServerKey: appServerKey,
                                            });
                                            const subJson = subscription.toJSON();
                                            await fetch('/health_pwa/api/push/subscribe', {
                                                method: 'POST',
                                                headers: { 'Content-Type': 'application/json' },
                                                body: JSON.stringify({ endpoint: subJson.endpoint, keys: subJson.keys }),
                                            });
                                            console.log('[PWA Push] Subscribed successfully');
                                            return true;
                                        } catch (err) {
                                            console.warn('[PWA Push] Subscribe failed:', err);
                                            return false;
                                        }
                                    };

                                    if (isIOS && !isStandalone) {
                                        console.log('[PWA Push] iOS Safari - push only works when installed to Home Screen');
                                    } else {
                                        // Check current permission state
                                        registration.pushManager.getSubscription().then(function(existingSub) {
                                            if (existingSub) {
                                                console.log('[PWA Push] Already subscribed');
                                                return;
                                            }
                                            // Not subscribed - check permission state and show appropriate banner
                                            var permState = ('Notification' in window) ? Notification.permission : 'default';
                                            if (permState === 'denied') {
                                                // Permission was denied - show settings instruction banner
                                                setTimeout(function() { _showPushBanner('denied'); }, 2000);
                                            } else if (isIOS) {
                                                // iOS needs user gesture - show enable banner
                                                setTimeout(function() { _showPushBanner('default'); }, 2000);
                                            } else {
                                                // Android/Desktop: try auto-subscribe first
                                                window._pwaPushSubscribe().then(function(ok) {
                                                    if (!ok) {
                                                        // If failed (denied/dismissed), show banner
                                                        setTimeout(function() { _showPushBanner(Notification.permission); }, 2000);
                                                    }
                                                });
                                            }
                                        });
                                    }
                                }
                            })
                            .catch(function(registrationError) {
                                console.log('SW registration failed: ', registrationError);
                            });
                    });
                }

                // Show update banner function
                function showUpdateBanner(registration) {
                    // Don't show banner if we just triggered an update (within last 10 seconds)
                    const lastUpdateTime = localStorage.getItem('pwa-update-triggered');
                    if (lastUpdateTime) {
                        const elapsed = Date.now() - parseInt(lastUpdateTime, 10);
                        if (elapsed < 10000) {  // 10 seconds grace period
                            console.log('[PWA] Skipping update banner - update was triggered', elapsed, 'ms ago');
                            localStorage.removeItem('pwa-update-triggered');
                            return;
                        }
                        localStorage.removeItem('pwa-update-triggered');
                    }

                    const banner = document.getElementById('pwa-update-banner');
                    if (banner) {
                        banner.style.display = 'flex';

                        // Auto-dismiss after 30 seconds and refresh
                        setTimeout(function() {
                            updateAndReload(registration);
                        }, 30000);
                    }
                }

                // Update and reload function
                function updateAndReload(registration) {
                    console.log('[PWA] Auto-updating service worker after 30 seconds...');
                    if (registration && registration.waiting) {
                        registration.waiting.postMessage({ type: 'SKIP_WAITING' });
                        // Wait a bit for the message to be processed, then reload
                        setTimeout(function() {
                            console.log('[PWA] Reloading page to activate new service worker');
                            window.location.reload();
                        }, 500);
                    } else {
                        console.log('[PWA] No waiting service worker, reloading anyway');
                        window.location.reload();
                    }
                }

                // Push Notification Permission Banner (works on both iOS and Android)
                function _showPushBanner(permissionState) {
                    // Remove any existing banner
                    var existing = document.getElementById('push-notif-banner');
                    if (existing) existing.remove();

                    var banner = document.createElement('div');
                    banner.id = 'push-notif-banner';
                    banner.style.cssText = 'position:fixed;bottom:0;left:0;right:0;z-index:9999;padding:20px 16px;padding-bottom:calc(20px + env(safe-area-inset-bottom,0px));color:#fff;box-shadow:0 -4px 24px rgba(0,0,0,0.25);animation:slideUpBanner 0.4s ease-out;font-family:-apple-system,BlinkMacSystemFont,sans-serif;';

                    // Add animation style once
                    if (!document.getElementById('push-banner-style')) {
                        var style = document.createElement('style');
                        style.id = 'push-banner-style';
                        style.textContent = '@keyframes slideUpBanner{from{transform:translateY(100%);opacity:0}to{transform:translateY(0);opacity:1}}';
                        document.head.appendChild(style);
                    }

                    if (permissionState === 'denied') {
                        // Permission was denied - show red banner with settings instructions
                        banner.style.background = 'linear-gradient(135deg,#e53935,#c62828)';
                        var isIOSDevice = /iPad|iPhone|iPod/.test(navigator.userAgent);
                        var settingsPath = isIOSDevice
                            ? 'Cài đặt → Safari → Thông báo / Settings → Safari → Notifications'
                            : 'Cài đặt → Thông báo → Chrome / Settings → Notifications → Chrome';
                        banner.innerHTML = '\
                            <div style="display:flex;align-items:flex-start;gap:12px">\
                                <div style="font-size:28px;line-height:1">🔕</div>\
                                <div style="flex:1">\
                                    <div style="font-weight:700;font-size:15px;margin-bottom:4px">Thông báo bị tắt / Notifications Blocked</div>\
                                    <div style="font-size:13px;opacity:0.95;margin-bottom:6px">Bạn cần bật thông báo trong Cài đặt để nhận lịch hẹn mới.</div>\
                                    <div style="font-size:12px;opacity:0.85;font-style:italic">Please enable notifications in your device Settings to receive booking alerts.</div>\
                                    <div style="margin-top:8px;padding:8px 12px;background:rgba(255,255,255,0.15);border-radius:8px;font-size:12px;font-weight:500">📱 ' + settingsPath + '</div>\
                                </div>\
                            </div>';
                    } else {
                        // Permission is 'default' - show green enable banner (no dismiss button)
                        banner.style.background = 'linear-gradient(135deg,#4CAF50,#2e7d32)';
                        banner.innerHTML = '\
                            <div style="display:flex;align-items:center;gap:12px">\
                                <div style="font-size:28px;line-height:1">🔔</div>\
                                <div style="flex:1">\
                                    <div style="font-weight:700;font-size:15px;margin-bottom:2px">Bật thông báo / Enable Notifications</div>\
                                    <div style="font-size:13px;opacity:0.9">Nhận thông báo ngay khi có lịch hẹn mới được giao cho bạn.</div>\
                                    <div style="font-size:12px;opacity:0.8;font-style:italic">Get instant alerts when a booking is assigned to you.</div>\
                                </div>\
                                <button id="push-enable-btn" style="padding:12px 20px;background:#fff;color:#2e7d32;border:none;border-radius:12px;font-weight:700;font-size:14px;cursor:pointer;white-space:nowrap;box-shadow:0 2px 8px rgba(0,0,0,0.15)">Bật / Enable</button>\
                            </div>';
                    }

                    document.body.appendChild(banner);

                    // Handle Enable button click
                    var enableBtn = document.getElementById('push-enable-btn');
                    if (enableBtn) {
                        enableBtn.addEventListener('click', async function() {
                            enableBtn.disabled = true;
                            enableBtn.textContent = '...';
                            var ok = await window._pwaPushSubscribe();
                            if (ok) {
                                banner.style.background = 'linear-gradient(135deg,#4CAF50,#2e7d32)';
                                banner.innerHTML = '
✅ Thông báo đã bật! / Notifications enabled!';
                                setTimeout(function() { banner.remove(); }, 2500);
                            } else {
                                // Permission was denied - show settings instructions
                                _showPushBanner('denied');
                            }
                        });
                    }
                }

                // PWA Install Prompt
                let deferredPrompt;
                window.addEventListener('beforeinstallprompt', function(e) {
                    e.preventDefault();
                    deferredPrompt = e;

                    // If smart install overlay is active (from ?install=1), show Android install section
                    if (window.healthPWAConfig && window.healthPWAConfig.showInstallOverlay) {
                        // Show the one-tap install button
                        const androidSection = document.getElementById('pwa-install-android');
                        if (androidSection) androidSection.style.display = 'block';
                        // Hide the manual guide since we have native prompt
                        const manualSection = document.getElementById('pwa-install-android-manual');
                        if (manualSection) manualSection.style.display = 'none';
                        // Hide iOS section
                        const iosSection = document.getElementById('pwa-install-ios');
                        if (iosSection) iosSection.style.display = 'none';
                    } else {
                        // Normal flow: Show install banner after 3 seconds
                        setTimeout(function() {
                            if (!localStorage.getItem('pwa-install-dismissed')) {
                                var banner = document.getElementById('pwa-install-banner');
                                if (banner) banner.style.display = 'block';
                            }
                        }, 3000);
                    }
                });

                // Install button handler
                document.addEventListener('DOMContentLoaded', function() {
                    // === Smart Install Overlay Logic ===
                    const installOverlay = document.getElementById('pwa-install-overlay');
                    const installCloseBtn = document.getElementById('pwa-install-close-btn');
                    const installNowBtn = document.getElementById('pwa-install-now-btn');

                    if (window.healthPWAConfig && window.healthPWAConfig.showInstallOverlay && installOverlay) {
                        // Check if already installed (standalone mode)
                        const isStandalone = window.matchMedia('(display-mode: standalone)').matches 
                                          || window.navigator.standalone === true;

                        if (isStandalone) {
                            // Already installed - show success message
                            installOverlay.style.display = 'flex';
                            const doneSection = document.getElementById('pwa-install-done');
                            if (doneSection) doneSection.style.display = 'block';
                            // Auto-close after 3 seconds
                            setTimeout(function() { installOverlay.style.display = 'none'; }, 3000);
                        } else {
                            // Show the overlay
                            installOverlay.style.display = 'flex';

                            // Detect platform
                            const isIOS = /iPad|iPhone|iPod/.test(navigator.userAgent) && !window.MSStream;

                            if (isIOS) {
                                // iOS: show visual guide (no native prompt available)
                                const iosSection = document.getElementById('pwa-install-ios');
                                if (iosSection) iosSection.style.display = 'block';
                            } else {
                                // Android/Desktop: check if native prompt is already available
                                if (deferredPrompt) {
                                    // Native prompt ready - show one-tap install button
                                    const androidSection = document.getElementById('pwa-install-android');
                                    if (androidSection) androidSection.style.display = 'block';
                                } else {
                                    // Native prompt not yet available - show manual guide immediately
                                    // If beforeinstallprompt fires later, it will swap to one-tap button
                                    const manualSection = document.getElementById('pwa-install-android-manual');
                                    if (manualSection) manualSection.style.display = 'block';
                                }
                            }
                        }
                    }

                    // Smart overlay: Install Now button (Android)
                    if (installNowBtn) {
                        installNowBtn.addEventListener('click', async function() {
                            if (deferredPrompt) {
                                deferredPrompt.prompt();
                                const { outcome } = await deferredPrompt.userChoice;
                                console.log('[PWA Install] User choice:', outcome);
                                if (outcome === 'accepted') {
                                    if (installOverlay) installOverlay.style.display = 'none';
                                }
                                deferredPrompt = null;
                            }
                        });
                    }

                    // Smart overlay: Close button
                    if (installCloseBtn) {
                        installCloseBtn.addEventListener('click', function() {
                            if (installOverlay) installOverlay.style.display = 'none';
                        });
                    }

                    // === Original install banner logic ===
                    const installBtn = document.getElementById('pwa-install-btn');
                    const dismissBtn = document.getElementById('pwa-dismiss-btn');
                    const installBanner = document.getElementById('pwa-install-banner');

                    if (installBtn) {
                        installBtn.addEventListener('click', async function() {
                            if (deferredPrompt) {
                                deferredPrompt.prompt();
                                const choiceResult = await deferredPrompt.userChoice;
                                if (choiceResult.outcome === 'accepted') {
                                    console.log('User accepted PWA install');
                                }
                                deferredPrompt = null;
                            }
                            installBanner.style.display = 'none';
                        });
                    }

                    if (dismissBtn) {
                        dismissBtn.addEventListener('click', function() {
                            localStorage.setItem('pwa-install-dismissed', 'true');
                            installBanner.style.display = 'none';
                        });
                    }

                    // Update button handler
                    const updateBtn = document.getElementById('pwa-update-btn');
                    // Hard reload helper to bust caches (especially on mobile)
                    const hardReload = () => {
                        const url = window.location.href.split('#')[0].split('?')[0];
                        window.location.href = `${url}?pwa_reload=${Date.now()}`;
                    };
                    let reloadScheduled = false;
                    const scheduleReload = (delay = 800) => {
                        if (reloadScheduled) return;
                        reloadScheduled = true;
                        setTimeout(() => {
                            console.log('Forcing hard reload for PWA update');
                            hardReload();
                        }, delay);
                    };
                    // Ensure controllerchange triggers reload (fallback for mobile)
                    if ('serviceWorker' in navigator) {
                        navigator.serviceWorker.addEventListener('controllerchange', () => {
                            console.log('[PWA] controllerchange fired, reloading now');
                            scheduleReload(100);
                        });
                    }

                    if (updateBtn) {
                        updateBtn.addEventListener('click', function() {
                            console.log('Update button clicked, triggering update...');

                            // Save timestamp to prevent banner from showing immediately after reload
                            localStorage.setItem('pwa-update-triggered', Date.now().toString());

                            // Hide the banner immediately
                            const banner = document.getElementById('pwa-update-banner');
                            if (banner) {
                                banner.style.display = 'none';
                            }

                            // Trigger update and reload
                            if (navigator.serviceWorker) {
                                navigator.serviceWorker.getRegistration().then(function(registration) {
                                    if (!registration) {
                                        console.log('No registration found, forcing hard reload');
                                        scheduleReload(200);
                                        return;
                                    }

                                    // Attempt update to fetch latest SW
                                    registration.update().finally(() => {
                                        if (registration.waiting) {
                                            console.log('Sending SKIP_WAITING to service worker');
                                            registration.waiting.postMessage({ type: 'SKIP_WAITING' });
                                            // If controllerchange does not fire, reload anyway
                                            scheduleReload(800);
                                        } else {
                                            console.log('[PWA] No waiting service worker after update(), forcing hard reload');
                                            scheduleReload(200);
                                        }
                                    });
                                });
                            } else {
                                console.log('[PWA] Service worker not supported, reloading');
                                scheduleReload(200);
                            }
                        });
                    }
                });

odoo.template:

// Health PWA Service Worker v1.13.1
// IMPORTANT: Increment version number when deploying updates!

const CACHE_VERSION = '1.13.1';
const CACHE_NAME = `health-pwa-v${CACHE_VERSION}`;
const OFFLINE_URL = '/health_pwa/offline';
const API_CACHE_NAME = `health-pwa-api-v${CACHE_VERSION}`;

// Listen for SKIP_WAITING message to activate new service worker immediately
self.addEventListener('message', (event) => {
    if (event.data && event.data.type === 'SKIP_WAITING') {
        self.skipWaiting();
    }
});

// Files to cache for offline functionality
const STATIC_CACHE_URLS = [
    '/health_pwa',
    '/health_pwa/offline',
    `/health_pwa/static/src/css/app.css?v=${CACHE_VERSION}`,
    `/health_pwa/static/src/css/mobile.css?v=${CACHE_VERSION}`,
    `/health_pwa/static/src/js/utils/pwa-utils.js?v=${CACHE_VERSION}`,
    `/health_pwa/static/src/js/app.js?v=${CACHE_VERSION}`,
    `/health_pwa/static/src/js/router.js?v=${CACHE_VERSION}`,
    '/health_pwa/static/icons/icon-192.png',
    // Note: External CDN URLs removed from pre-cache - they fail with CORS errors
    // and cause the entire SW installation to fail, preventing cache updates.
    // These are loaded directly via <script> tags and cached by the browser normally.
];

// API endpoints to cache
const API_CACHE_PATTERNS = [
    /^\/health_pwa\/api\/patients/,
    /^\/health_pwa\/api\/fso/,
    /^\/health_pwa\/api\/teams/,
    /^\/health_pwa\/api\/user/,
];

// Install event - cache static files
self.addEventListener('install', event => {
    console.log('Service Worker installing...');
    event.waitUntil(
        caches.open(CACHE_NAME)
            .then(cache => {
                console.log('Caching static files');
                return cache.addAll(STATIC_CACHE_URLS);
            })
            .then(() => {
                console.log('Service Worker installed successfully');
                return self.skipWaiting();
            })
            .catch(error => {
                console.error('Service Worker installation failed:', error);
            })
    );
});

// Activate event - clean up old caches
self.addEventListener('activate', event => {
    console.log('Service Worker activating...');
    event.waitUntil(
        caches.keys().then(cacheNames => {
            return Promise.all(
                cacheNames.map(cacheName => {
                    if (cacheName !== CACHE_NAME && cacheName !== API_CACHE_NAME) {
                        console.log('Deleting old cache:', cacheName);
                        return caches.delete(cacheName);
                    }
                })
            );
        }).then(() => {
            console.log('Service Worker activated');
            return self.clients.claim();
        })
    );
});

// Fetch event - handle network requests with caching strategy
self.addEventListener('fetch', event => {
    const request = event.request;
    const url = new URL(request.url);

    // Skip non-GET requests and chrome-extension requests
    if (request.method !== 'GET' || url.protocol === 'chrome-extension:') {
        return;
    }

    // Handle PWA app requests
    if (url.pathname.startsWith('/health_pwa')) {
        if (url.pathname.startsWith('/health_pwa/api/') || url.pathname.startsWith('/health_pwa/sync/')) {
            // EVV endpoints (health_evv) are NETWORK-ONLY: hash-chained
            // verification data must never be served from cache.
            if (url.pathname.includes('/evv/')) {
                return; // default browser networking, no cache read/write
            }
            // API requests - Network First with Cache Fallback
            event.respondWith(handleAPIRequest(request));
        } else if (request.mode === 'navigate' || url.pathname === '/health_pwa' || url.pathname === '/health_pwa/') {
            // Navigation requests (HTML) - Network First to always get latest version
            event.respondWith(handleNavigationRequest(request));
        } else {
            // Static files (JS, CSS, images) - Cache First (versioned via query param)
            event.respondWith(handleStaticRequest(request));
        }
    }
});
// Handle navigation (HTML page) requests with Network First strategy
async function handleNavigationRequest(request) {
    try {
        const response = await fetch(request);
        if (response.ok) {
            // Cache the latest HTML for offline use
            const cache = await caches.open(CACHE_NAME);
            cache.put(request, response.clone());
        }
        return response;
    } catch (error) {
        console.log('Navigation fetch failed, using cache');
        const cache = await caches.open(CACHE_NAME);
        const cachedResponse = await cache.match(request);
        if (cachedResponse) return cachedResponse;
        // Fallback to offline page
        const offlineResponse = await cache.match(OFFLINE_URL);
        return offlineResponse || new Response('Offline', { status: 503 });
    }
}

// Handle API requests with Network First strategy
async function handleAPIRequest(request) {
    const url = new URL(request.url);

    try {
        // Try network first
        const response = await fetch(request);

        // Cache successful GET responses for offline use
        if (response.ok && request.method === 'GET') {
            const cache = await caches.open(API_CACHE_NAME);
            cache.put(request, response.clone());
        }

        return response;
    } catch (error) {
        console.log('Network failed, trying cache for:', url.pathname);

        // Network failed, try cache
        const cache = await caches.open(API_CACHE_NAME);
        const cachedResponse = await cache.match(request);

        if (cachedResponse) {
            // Add offline indicator header
            const response = cachedResponse.clone();
            response.headers.set('X-Served-By', 'ServiceWorker-Cache');
            return response;
        }

        // Return offline response for API requests
        return new Response(JSON.stringify({
            success: false,
            error: 'Network unavailable and no cached data',
            offline: true,
            timestamp: new Date().toISOString()
        }), {
            status: 503,
            headers: { 'Content-Type': 'application/json' }
        });
    }
}

// Handle static requests with Cache First strategy
async function handleStaticRequest(request) {
    const cache = await caches.open(CACHE_NAME);
    const cachedResponse = await cache.match(request);

    if (cachedResponse) {
        return cachedResponse;
    }

    try {
        const response = await fetch(request);
        if (response.ok) {
            cache.put(request, response.clone());
        }
        return response;
    } catch (error) {
        console.log('Static request failed:', request.url);

        // Return offline page for navigation requests
        if (request.mode === 'navigate') {
            const offlineResponse = await cache.match(OFFLINE_URL);
            return offlineResponse || new Response('Offline', { status: 503 });
        }

        // Return minimal response for other requests
        return new Response('Offline', { status: 503 });
    }
}

// Background sync for offline actions
self.addEventListener('sync', event => {
    console.log('Background sync triggered:', event.tag);

    if (event.tag === 'health-pwa-sync') {
        event.waitUntil(performBackgroundSync());
    }

    // EVV offline queue (health_evv): the actual flush runs in app
    // context where the local store lives — just wake the clients.
    if (event.tag === 'evv-flush') {
        event.waitUntil(
            self.clients.matchAll({ includeUncontrolled: true }).then(clients => {
                clients.forEach(client => client.postMessage({ type: 'EVV_FLUSH' }));
            })
        );
    }
});

// Perform background sync
async function performBackgroundSync() {
    try {
        // Get pending sync data from IndexedDB (handled by PouchDB)
        console.log('Performing background sync...');

        // Send message to active clients to trigger sync
        const clients = await self.clients.matchAll();
        clients.forEach(client => {
            client.postMessage({
                type: 'BACKGROUND_SYNC',
                timestamp: new Date().toISOString()
            });
        });

    } catch (error) {
        console.error('Background sync failed:', error);
    }
}

// Push notification handler
self.addEventListener('push', event => {
    console.log('[SW] Push notification received');

    let notifData = {
        title: 'Viet Uc Care',
        body: 'New notification',
        icon: '/health_pwa/static/icons/icon-192.png',
        badge: '/health_pwa/static/icons/icon-96.png',
        tag: 'health-pwa-notification',
        data: {},
    };

    if (event.data) {
        try {
            const payload = event.data.json();
            notifData.title = payload.title || notifData.title;
            notifData.body = payload.body || notifData.body;
            notifData.icon = payload.icon || notifData.icon;
            notifData.badge = payload.badge || notifData.badge;
            notifData.tag = payload.tag || notifData.tag;
            notifData.data = payload.data || {};
        } catch (e) {
            notifData.body = event.data.text();
        }
    }

    // Build notification actions based on type
    let actions = [
        { action: 'open', title: 'Mở / Open' },
        { action: 'close', title: 'Đóng / Close' }
    ];

    // Assignment notifications get Accept/Decline buttons
    if (notifData.data && notifData.data.type === 'assignment' && notifData.data.assignment_id) {
        actions = [
            { action: 'accept', title: '✅ Accept' },
            { action: 'decline', title: '❌ Decline' },
        ];
    }

    const options = {
        body: notifData.body,
        icon: notifData.icon,
        badge: notifData.badge,
        vibrate: [200, 100, 200],
        tag: notifData.tag,
        data: notifData.data,
        actions: actions,
        requireInteraction: true,
    };

    event.waitUntil(
        self.registration.showNotification(notifData.title, options).then(() => {
            // Notify all open clients to refresh notification count
            return self.clients.matchAll({ type: 'window' }).then(clientList => {
                clientList.forEach(client => {
                    client.postMessage({ type: 'PUSH_RECEIVED' });
                });
            });
        })
    );
});

// Notification click handler
self.addEventListener('notificationclick', event => {
    console.log('[SW] Notification clicked:', event.action);
    event.notification.close();

    if (event.action === 'close') return;

    const notifData = event.notification.data || {};
    const assignmentId = notifData.assignment_id;

    // Handle Accept/Decline actions for assignments
    if (assignmentId && (event.action === 'accept' || event.action === 'decline')) {
        event.waitUntil(
            fetch(`/health_pwa/api/assignments/${assignmentId}/respond`, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ action: event.action }),
            }).then(resp => resp.json()).then(data => {
                console.log('[SW] Assignment response:', data);
                // Notify clients to refresh
                return self.clients.matchAll({ type: 'window' }).then(clientList => {
                    clientList.forEach(client => {
                        client.postMessage({ type: 'PUSH_RECEIVED' });
                    });
                    // If no open clients, show a confirmation notification
                    if (clientList.length === 0) {
                        const msg = event.action === 'accept'
                            ? '✅ Assignment confirmed'
                            : '❌ Assignment declined';
                        return self.registration.showNotification('Viet Uc Care', {
                            body: msg,
                            icon: '/health_pwa/static/icons/icon-192.png',
                            tag: 'assignment-response',
                        });
                    }
                });
            }).catch(err => {
                console.error('[SW] Failed to respond to assignment:', err);
                return self.registration.showNotification('Viet Uc Care', {
                    body: '⚠️ Error responding to assignment. Please open the app.',
                    icon: '/health_pwa/static/icons/icon-192.png',
                    tag: 'assignment-response-error',
                });
            })
        );
        return;
    }

    // Default: open the app (with notifications panel if assignment)
    // A family_message push opens the shared booking modal for that visit via
    // the #/order/ID deep link (the app maps it to openBooking()).
    const urlToOpen = (notifData && notifData.type === 'assignment')
        ? '/health_pwa#/today?showNotifications=1'
        : (notifData && notifData.type === 'family_message' && notifData.fso_id)
            ? ('/health_pwa#/order/' + notifData.fso_id)
            : (notifData && notifData.url)
                ? notifData.url
                : '/health_pwa';

    event.waitUntil(
        clients.matchAll({ type: 'window', includeUncontrolled: true }).then(clientList => {
            // Try to focus existing window
            for (const client of clientList) {
                if (client.url.includes('/health_pwa') && 'focus' in client) {
                    client.navigate(urlToOpen);
                    return client.focus();
                }
            }
            // Open new window if no existing window
            if (clients.openWindow) {
                return clients.openWindow(urlToOpen);
            }
        })
    );
});

console.log('Health PWA Service Worker loaded successfully');

div.script:
// Auto-retry when back online
window.addEventListener('online', function() {
    setTimeout(function() {
        window.location.reload();
    }, 1000);
});

// User language preference from profile
const userLangPreference = '';

// Determine initial language (vi or en)
function getInitialLanguage() {
    // Priority: 1. User profile preference, 2. localStorage, 3. Default to 'vi'
    if (userLangPreference) {
        // Odoo lang codes: en_US, vi_VN, etc.
        if (userLangPreference.startsWith('en')) {
            return 'en';
        } else if (userLangPreference.startsWith('vi')) {
            return 'vi';
        }
    }
    return localStorage.getItem('preferredLanguage') || 'vi';
}

// Language switching
function switchLanguage(lang) {
    // Update active language button
    document.querySelectorAll('.lang-btn').forEach(btn => btn.classList.remove('active'));
    document.getElementById('btn-' + lang).classList.add('active');

    // Show/hide language-specific content
    document.querySelectorAll('.lang-content').forEach(el => el.classList.remove('active'));
    document.querySelectorAll('.lang-content[id$="-' + lang + '"]').forEach(el => el.classList.add('active'));

    // Save preference
    localStorage.setItem('preferredLanguage', lang);
}

// Load preferred language on page load
window.addEventListener('DOMContentLoaded', function() {
    const initialLang = getInitialLanguage();
    switchLanguage(initialLang);

    // Generate QR Code
    const currentUrl = window.location.href;
    if (typeof QRCode !== 'undefined') {
        new QRCode(document.getElementById('qrcode'), {
            text: currentUrl,
            width: 200,
            height: 200,
            colorDark: '#1565C0',
            colorLight: '#ffffff',
            correctLevel: QRCode.CorrectLevel.H
        });
    }

    // Handle beforeinstallprompt for Android
    let deferredPrompt;
    window.addEventListener('beforeinstallprompt', (e) => {
        e.preventDefault();
        deferredPrompt = e;
        // Show install button
        const installBtn = document.getElementById('installBtn');
        if (installBtn) {
            installBtn.style.display = 'block';
        }
    });

    // Install button click handler
    const installBtn = document.getElementById('installBtn');
    if (installBtn) {
        installBtn.addEventListener('click', async () => {
            if (deferredPrompt) {
                deferredPrompt.prompt();
                const { outcome } = await deferredPrompt.userChoice;
                console.log(`User response to install prompt: ${outcome}`);
                deferredPrompt = null;
                installBtn.style.display = 'none';
            }
        });
    }

    // Platform detection for video embedding (placeholder for future videos)
    const isIOS = /iPad|iPhone|iPod/.test(navigator.userAgent) && !window.MSStream;
    const isAndroid = /Android/.test(navigator.userAgent);

    // Video embedding can be added here when videos are ready
    // Example:
    // if (isIOS) {
    //     document.getElementById('video-container').innerHTML = '';
    //     document.getElementById('video-section').style.display = 'block';
    // } else if (isAndroid) {
    //     document.getElementById('video-container').innerHTML = '';
    //     document.getElementById('video-section').style.display = 'block';
    // }
});
